import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../../../Core/Resources/app_colors.dart';import '../../../../../../Core/Resources/app_fonts.dart';import '../Manager/product_details_cubit.dart';class ProductInformation extends StatelessWidget {  const ProductInformation({super.key});  @override  Widget build(BuildContext context) {    final details = context.read<ProductDetailsCubit>().state.product;    final statusProducts = details?.status == 1;    return ListView(      physics: NeverScrollableScrollPhysics(),      children: [        Row(          crossAxisAlignment: CrossAxisAlignment.start,          children: [            Expanded(              child: Text(                details?.name ?? "",                style: AppTextStyles.h4Bold                    .copyWith(color: AppColors.secondaryColor),              ),            ),            Container(              padding: EdgeInsets.symmetric(horizontal: 8, vertical: 4),              decoration: BoxDecoration(                color: statusProducts                    ? AppColors.success.withAlpha(100)                    : AppColors.error.withAlpha(100),                borderRadius: BorderRadius.circular(12).r,              ),              child: Text(                statusProducts ? "In Stock" : "Out of Stock",                style: AppTextStyles.bodyXtraSmallBold                    .copyWith(color: AppColors.secondaryColor),              ),            ),          ],        ),        8.verticalSpace,        // Dimensions        Text(          "${details?.dimensions} CM",          style: AppTextStyles.bodySmallSemiBold.copyWith(            color: AppColors.textColorBlack,          ),        ),        8.verticalSpace,        // Rating and Reviews        Row(          children: [            // Star Ratings            ...List.generate(              5,              (index) => Icon(                Icons.star,                color: index < 0 ? AppColors.star : AppColors.grayscale70,                size: 18.w,              ),            ),            5.horizontalSpace,            Text(              details?.reviews.length.toString() ?? "0",              style: AppTextStyles.bodySmallSemiBold.copyWith(                color: AppColors.grayscale70,              ),            ),            5.horizontalSpace,            Text(              "( ${details?.reviews.length.toString() ?? "0"} Reviews)",              style: AppTextStyles.bodySmallSemiBold.copyWith(                color: AppColors.grayscale70,              ),            ),          ],        ),        8.verticalSpace,        // Price        Row(          children: [            Text(              "\$ ${details?.discountPrice}",              style: AppTextStyles.bodyMediumBold.copyWith(                color: AppColors.textColorBlack,              ),            ),            8.horizontalSpace,            Text(              "\$ ${details?.price}",              style: AppTextStyles.bodyMediumBold.copyWith(                decoration: TextDecoration.lineThrough,                color: AppColors.grayscale70,              ),            ),          ],        ),        12.verticalSpace,        // Description        Text(          "${details?.description}\n---\n${details?.additionalInfo}",          style: AppTextStyles.bodyMediumBold.copyWith(            color: AppColors.textColorBlack,          ),        ),        16.verticalSpace,        // Color Options        Text("Color",            style: AppTextStyles.h4Bold.copyWith(              color: AppColors.textColorBlack,            )),        8.verticalSpace,        Row(          children: [            ...List.generate(              details?.colors.length ?? 0,              (index) => _buildColorOption(                  ("0xff${details!.colors[index].code.split("#").last}")),            ),          ],        ),        16.verticalSpace,        // Size Options        Text("Size",            style: AppTextStyles.h4Bold.copyWith(              color: AppColors.textColorBlack,            )),        2.verticalSpace,        Row(          children: [            ...List.generate(              details?.sizes.length ?? 0,              (index) => _buildSizeOption(                  details?.sizes[index].name.substring(0, 2).toUpperCase() ??                      ""),            )          ],        ),      ],    );  }  // Color Option Widget  Widget _buildColorOption(String colors) {    final color = int.parse(colors);    return Container(      margin: EdgeInsets.only(right: 8).w,      width: 28,      height: 28,      decoration: BoxDecoration(        color: Color(color),        shape: BoxShape.circle,        border: Border.all(color: Colors.grey.shade300, width: 1),      ),    );  }  // Size Option Widget  Widget _buildSizeOption(String size, {bool selected = false}) {    return Container(      margin: EdgeInsets.only(right: 8),      padding: EdgeInsets.symmetric(horizontal: 12, vertical: 8),      decoration: BoxDecoration(        color: selected ? Colors.black : Colors.white,        borderRadius: BorderRadius.circular(8),        border: Border.all(color: Colors.black),      ),      child: Text(        size,        style: TextStyle(            color: selected ? Colors.white : Colors.black, fontSize: 14.sp),      ),    );  }}